extends CharacterBody2D

const SPEED = 200

func _physics_process(delta: float) -> void:
	if Input.is_action_pressed("ui_right"):
		velocity.x = SPEED
	else:
		velocity.x = 0

	move_and_slide()

extends CharacterBody2D

const GRAVITY = 980

func _physics_process(delta):
	if not is_on_floor():
		velocity.y += GRAVITY * delta
	else:
		velocity.y = 0

	move_and_slide()

extends RefCounted

static func save_data(data: Dictionary, path: String) -> void:
	var json_string = JSON.stringify(data)
	var file = FileAccess.open(path, FileAccess.WRITE)
	if file:
		file.store_string(json_string)

static func load_data(path: String) -> Dictionary:
	var file = FileAccess.open(path, FileAccess.READ)
	if file:
		var json_string = file.get_as_text()
		var parsed = JSON.parse_string(json_string)
		if parsed is Dictionary:
			return parsed
	return {}

extends Node

var spawned_count = 0

func _ready():
	var timer = Timer.new()
	add_child(timer)
	timer.wait_time = 0.25
	timer.timeout.connect(_on_timer_timeout)
	timer.start()

func _on_timer_timeout():
	var new_node = Node2D.new()
	add_child(new_node)
	spawned_count += 1

	if spawned_count >= 4:
		var timer = get_child(0)
		timer.stop()

extends RefCounted

var _items: Dictionary = {}

func add_item(item_name: String, count: int) -> void:
	if item_name in _items:
		_items[item_name] += count
	else:
		_items[item_name] = count

func remove_item(item_name: String, count: int) -> bool:
	if item_name not in _items or _items[item_name] < count:
		return false
	_items[item_name] -= count
	return true

func get_count(item_name: String) -> int:
	return _items.get(item_name, 0)

extends Node

func load_level(path: String) -> Node:
	var scene = load(path)
	var instance = scene.instantiate()
	add_child(instance)
	return instance

extends TileMapLayer

func paint_row(y: int, from_x: int, to_x: int) -> void:
	for x in range(from_x, to_x + 1):
		set_cell(Vector2i(x, y), 0, Vector2i(0, 0))

func is_painted(cell: Vector2i) -> bool:
	return get_cell_source_id(cell) != -1

extends Node2D

func first_hit(from: Vector2, to: Vector2) -> Vector2:
	var space_state = get_world_2d().direct_space_state
	var query = PhysicsRayQueryParameters2D.create(from, to)
	var result = space_state.intersect_ray(query)

	if result:
		return result.position
	else:
		return to

extends RefCounted

func find_path(size: Vector2i, walls: Array[Vector2i], from: Vector2i, to: Vector2i) -> Array[Vector2i]:
	if from == to:
		return [from]

	var wall_set = {}
	for wall in walls:
		wall_set[wall] = true

	var queue = [[from]]
	var visited = {from: true}

	while queue.size() > 0:
		var path = queue.pop_front()
		var current = path[-1]

		var directions = [
			Vector2i(0, -1),
			Vector2i(0, 1),
			Vector2i(-1, 0),
			Vector2i(1, 0)
		]

		for direction in directions:
			var next = current + direction

			if next.x < 0 or next.x >= size.x or next.y < 0 or next.y >= size.y:
				continue

			if visited.has(next) or wall_set.has(next):
				continue

			if next == to:
				return path + [next]

			visited[next] = true
			queue.append(path + [next])

	return []

